try{const pdf=await pdfjsLib.getDocument({url:'document_stream.php?id=<?=$id?>',withCredentials:true}).promise;root.innerHTML='';for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n),viewport=page.getViewport({scale:Math.min(1.8,Math.max(1,window.devicePixelRatio||1))}),canvas=document.createElement('canvas');canvas.className='pdf-page';canvas.width=viewport.width;canvas.height=viewport.height;canvas.setAttribute('aria-label','Página '+n);root.append(canvas);await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;const tag=document.createElement('small');tag.textContent=watermark;tag.style.cssText='position:absolute;opacity:.18;font:10px Manrope;color:#101828;pointer-events:none';canvas.parentElement?.append(tag);}}catch(e){root.innerHTML='<p class="alert err">Não foi possível carregar este material. Atualize a página ou fale com o suporte.</p>';}
